-- Disposable local seeded database only; all fixture changes roll back.
\set ON_ERROR_STOP on
begin;
create function pg_temp.check_it(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; end $$;
create function pg_temp.denied(q text,expected text) returns void language plpgsql as $$ begin begin execute q; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise exception 'Wrong refusal: %',sqlerrm; end; raise exception 'Unexpected success: %',q; end $$;
create temp table f(k text primary key,v uuid); grant all on f to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
insert into f values('covered',fn_record_meter_reading('55555555-0000-0000-0000-000000000001',100,now(),gen_random_uuid()));
insert into f values('old',fn_record_meter_reading('55555555-0000-0000-0000-000000000002',100,now(),gen_random_uuid()));
insert into f values('stale',fn_record_meter_reading('55555555-0000-0000-0000-000000000003',100,now(),gen_random_uuid()));
insert into f values('paid',fn_record_meter_reading('55555555-0000-0000-0000-000000000004',100,now(),gen_random_uuid()));
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000001',true);
select fn_post_bill_amount(v,249.40,fn_ph_today()+1,now(),gen_random_uuid()) from f;
reset role;
update bills set due_date=fn_ph_today()-1 where id=(select v from f where k='old');
select app.run_boheco_cutoffs();
select pg_temp.check_it((select state='awaiting_referral' and route='boheco' and referred_at is null from bill_settlements where bill_id=(select v from f where k='old')),'Overdue routes even before configured cutoff');
select pg_temp.check_it((select count(*)=1 from notifications where bill_id=(select v from f where k='old') and channel='push' and notif_type='overdue'),'Routing notification queued once');
select app.run_boheco_cutoffs();
select pg_temp.check_it((select count(*)=1 from notifications where bill_id=(select v from f where k='old') and channel='push' and notif_type='overdue'),'Repeat job is idempotent');
select pg_temp.check_it(not exists(select 1 from bill_settlements where bill_id=(select v from f where k='covered')),'Overdue routing does not close other collections');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
select fn_close_boheco_trip(date_trunc('month',fn_ph_today())::date);
reset role;
insert into f select 'trip',trip_id from bill_settlements where bill_id=(select v from f where k='covered');
select pg_temp.check_it((select state='review' from bill_settlements where bill_id=(select v from f where k='covered')),'Not overdue remains eligible');
update bills set due_date=fn_ph_today()-1 where id=(select v from f where k='stale');
update bills set external_paid=250 where id=(select v from f where k='paid');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000003',true);
select fn_pondo_entry(1000,'opening','Test cash',gen_random_uuid());
select pg_temp.denied(format('select fn_allocate_boheco_trip(%L,array[%L::uuid],array[250::numeric],%L)',(select v from f where k='trip'),(select v from f where k='stale'),'33333333-0000-0000-0000-000000000002'),'Bill paid, overdue or changed');
select pg_temp.denied(format('select fn_allocate_boheco_trip(%L,array[%L::uuid],array[250::numeric],%L)',(select v from f where k='trip'),(select v from f where k='paid'),'33333333-0000-0000-0000-000000000002'),'Bill paid, overdue or changed');
select fn_allocate_boheco_trip((select v from f where k='trip'),array[(select v from f where k='covered')],array[250::numeric],'33333333-0000-0000-0000-000000000002');
select pg_temp.check_it((select state='settled' from bill_settlements where bill_id=(select v from f where k='paid')),'Paid unselected bill not referred');
select pg_temp.denied(format('select fn_complete_boheco_trip(%L,array[]::uuid[])',(select v from f where k='trip')),'required role');
reset role;
update bills set due_date=fn_ph_today()-1 where id=(select v from f where k='covered');
select app.run_boheco_cutoffs();
select pg_temp.check_it((select route='pondo' and state='handed_over' from bill_settlements where bill_id=(select v from f where k='covered')),'Handed cash protects coverage past due date');
select pg_temp.check_it((select sum(amount)=750.60 from pondo_ledger),'Only selected coverage debited');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
select pg_temp.denied(format('select fn_complete_boheco_trip(%L,array[]::uuid[])',(select v from f where k='trip')),'record reserve fund');
-- Direct receipt may be verified without a separate referral tap.
select fn_confirm_boheco_payment((select v from f where k='old'),249.40,'TEST-DIRECT',now(),'Verified BOHECO receipt',gen_random_uuid());
select pg_temp.check_it((select balance=0 from bills where id=(select v from f where k='old')),'Verified direct payment clears local bill');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000001',true);
select fn_correct_settlement_checked((select v from f where k='covered'),'Cash physically returned','return_funds',
 (select updated_at from bill_settlements where bill_id=(select v from f where k='covered')),gen_random_uuid());
select pg_temp.check_it((select sum(amount)=1000 from pondo_ledger),'Returned cash restored once');
select pg_temp.denied(format('select fn_correct_settlement(%L,''Retry'')',(select v from f where k='covered')),'permission denied');
select pg_temp.denied($q$select fn_issue_disconnection_notice('55555555-0000-0000-0000-000000000001','Not reported',now(),gen_random_uuid())$q$,'confirmed BOHECO referral');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000004',true);
select pg_temp.denied(format('select fn_complete_boheco_trip(%L,array[]::uuid[])',(select v from f where k='trip')),'unavailable');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
select pg_temp.denied(format('select fn_complete_boheco_trip(%L,array[]::uuid[])',(select v from f where k='trip')),'Trip changed');
select fn_complete_boheco_trip((select v from f where k='trip'),array[(select v from f where k='covered'),(select v from f where k='stale')]);
select fn_complete_boheco_trip((select v from f where k='trip'),array[(select v from f where k='covered'),(select v from f where k='stale')]);
select pg_temp.check_it((select count(*)=2 from bill_settlements where state='referred' and referred_at is not null),'Trip reports both uncovered bills');
select pg_temp.check_it((select count(*)=1 from settlement_audit where action='trip_completed'),'Retry cannot duplicate trip completion');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000001',true);
select fn_issue_disconnection_notice('55555555-0000-0000-0000-000000000001','Unpaid after reported trip',now(),gen_random_uuid());
select pg_temp.check_it((select count(*)=1 from notifications where notif_type='disconnection' and channel='sms'),'Notice SMS only after confirmed report');
rollback;
